import math
def solve(x, grad, gamma=None, eps=1e-5):
    n=len(x); gamma=gamma or [1.0]*n; mu=sum(x)/n
    var=sum((v-mu)**2 for v in x)/n; inv=1/math.sqrt(var+eps)
    z=[(v-mu)*inv for v in x]; g=[grad[i]*gamma[i] for i in range(n)]
    return [inv*(g[i]-sum(g)/n-z[i]*sum(g[j]*z[j] for j in range(n))/n) for i in range(n)]

